// dp[l][r] = min multiplications for matrices l..r; dims p[0..n]
for (int len = 2; len <= n; ++len)
  for (int l = 1; l + len - 1 <= n; ++l) {
    int r = l + len - 1; dp[l][r] = INT_MAX;
    for (int k = l; k < r; ++k)
      dp[l][r] = min(dp[l][r],
        dp[l][k] + dp[k+1][r] + p[l-1]*p[k]*p[r]);
  }

class Solution {
public:
    int maxCoins(vector<int>& nums) {
        int n = nums.size();
        vector<int> a(n + 2, 1);
        for (int i = 0; i < n; i++) a[i + 1] = nums[i];
        vector<vector<int>> dp(n + 2, vector<int>(n + 2, 0));
        for (int len = 2; len <= n + 1; len++)
            for (int i = 0; i + len <= n + 1; i++) {
                int j = i + len;
                for (int k = i + 1; k < j; k++)
                    dp[i][j] = max(dp[i][j], dp[i][k] + a[i] * a[k] * a[j] + dp[k][j]);
            }
        return dp[0][n + 1];
    }
};

class Solution:
    def maxCoins(self, nums: list[int]) -> int:
        a = [1] + nums + [1]
        n = len(a)
        dp = [[0] * n for _ in range(n)]
        for length in range(2, n):
            for i in range(n - length):
                j = i + length
                for k in range(i + 1, j):
                    dp[i][j] = max(dp[i][j], dp[i][k] + a[i] * a[k] * a[j] + dp[k][j])
        return dp[0][n - 1]

class Solution {
public:
    int minScoreTriangulation(vector<int>& v) {
        int n = v.size();
        vector<vector<int>> dp(n, vector<int>(n, 0));
        for (int len = 2; len < n; len++)
            for (int i = 0; i + len < n; i++) {
                int j = i + len; dp[i][j] = INT_MAX;
                for (int k = i + 1; k < j; k++)
                    dp[i][j] = min(dp[i][j], dp[i][k] + dp[k][j] + v[i] * v[k] * v[j]);
            }
        return dp[0][n - 1];
    }
};

class Solution:
    def minScoreTriangulation(self, v: list[int]) -> int:
        n = len(v)
        dp = [[0] * n for _ in range(n)]
        for length in range(2, n):
            for i in range(n - length):
                j = i + length
                dp[i][j] = min(dp[i][k] + dp[k][j] + v[i] * v[k] * v[j] for k in range(i + 1, j))
        return dp[0][n - 1]

class Solution {
public:
    bool stoneGame(vector<int>& a) {
        int n = a.size();
        vector<vector<int>> dp(n, vector<int>(n, 0));
        for (int i = 0; i < n; i++) dp[i][i] = a[i];
        for (int len = 1; len < n; len++)
            for (int i = 0; i + len < n; i++) {
                int j = i + len;
                dp[i][j] = max(a[i] - dp[i + 1][j], a[j] - dp[i][j - 1]);
            }
        return dp[0][n - 1] > 0;
    }
};

class Solution:
    def stoneGame(self, a: list[int]) -> bool:
        n = len(a)
        dp = [[0] * n for _ in range(n)]
        for i in range(n):
            dp[i][i] = a[i]
        for length in range(1, n):
            for i in range(n - length):
                j = i + length
                dp[i][j] = max(a[i] - dp[i + 1][j], a[j] - dp[i][j - 1])
        return dp[0][n - 1] > 0

class Solution {
public:
    int strangePrinter(string s) {
        int n = s.size();
        if (n == 0) return 0;
        vector<vector<int>> dp(n, vector<int>(n, 0));
        for (int i = 0; i < n; i++) dp[i][i] = 1;
        for (int len = 1; len < n; len++)
            for (int i = 0; i + len < n; i++) {
                int j = i + len;
                dp[i][j] = dp[i + 1][j] + 1;
                for (int k = i + 1; k <= j; k++)
                    if (s[k] == s[i])
                        dp[i][j] = min(dp[i][j], dp[i + 1][k - 1] + dp[k][j]);
            }
        return dp[0][n - 1];
    }
};

class Solution:
    def strangePrinter(self, s: str) -> int:
        n = len(s)
        if n == 0:
            return 0
        dp = [[0] * n for _ in range(n)]
        for i in range(n):
            dp[i][i] = 1
        for length in range(1, n):
            for i in range(n - length):
                j = i + length
                dp[i][j] = dp[i + 1][j] + 1
                for k in range(i + 1, j + 1):
                    if s[k] == s[i]:
                        left = dp[i + 1][k - 1] if k - 1 >= i + 1 else 0
                        dp[i][j] = min(dp[i][j], left + dp[k][j])
        return dp[0][n - 1]

class Solution {
public:
    int minCut(string s) {
        int n = s.size();
        vector<vector<bool>> pal(n, vector<bool>(n, false));
        for (int i = n - 1; i >= 0; i--)
            for (int j = i; j < n; j++)
                pal[i][j] = s[i] == s[j] && (j - i < 2 || pal[i + 1][j - 1]);
        vector<int> cut(n, 0);
        for (int i = 0; i < n; i++) {
            if (pal[0][i]) { cut[i] = 0; continue; }
            cut[i] = i;
            for (int j = 1; j <= i; j++)
                if (pal[j][i]) cut[i] = min(cut[i], cut[j - 1] + 1);
        }
        return cut[n - 1];
    }
};

class Solution:
    def minCut(self, s: str) -> int:
        n = len(s)
        pal = [[False] * n for _ in range(n)]
        for i in range(n - 1, -1, -1):
            for j in range(i, n):
                pal[i][j] = s[i] == s[j] and (j - i < 2 or pal[i + 1][j - 1])
        cut = [0] * n
        for i in range(n):
            if pal[0][i]:
                cut[i] = 0
                continue
            cut[i] = i
            for j in range(1, i + 1):
                if pal[j][i]:
                    cut[i] = min(cut[i], cut[j - 1] + 1)
        return cut[n - 1]
